                testAllocator_sliceUpBufferAndRelease(rootAllocator, childAllocator);
                arrowBuf1.release();
                rootAllocator.verify();
            }
            rootAllocator.verify();
            testAllocator_sliceUpBufferAndRelease(rootAllocator, childAllocator);
        }
        rootAllocator.verify();
