        /* listVector has 2 lists at index 0 and 3 lists at index 1 */
        assertEquals(0, offsetBuffer.getInt(0 * ListVector.OFFSET_WIDTH));
        assertEquals(2, offsetBuffer.getInt(1 * ListVector.OFFSET_WIDTH));
